PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS sporting_sports (id TEXT PRIMARY KEY, school_id TEXT NOT NULL REFERENCES schools(id), name TEXT NOT NULL, description TEXT, active INTEGER NOT NULL DEFAULT 1, gender_category TEXT, age_category TEXT, responsible_teacher TEXT, academic_year_id TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, UNIQUE(school_id, name, academic_year_id));
CREATE TABLE IF NOT EXISTS sporting_teams (id TEXT PRIMARY KEY, school_id TEXT NOT NULL REFERENCES schools(id), name TEXT NOT NULL, code TEXT, coach TEXT, captain TEXT, vice_captain TEXT, active INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, UNIQUE(school_id, name));
CREATE TABLE IF NOT EXISTS sporting_activities (id TEXT PRIMARY KEY, school_id TEXT NOT NULL REFERENCES schools(id), title TEXT NOT NULL, sport_id TEXT NOT NULL REFERENCES sporting_sports(id), competition_type TEXT NOT NULL, academic_year_id TEXT NOT NULL, term_id TEXT NOT NULL, event_date TEXT NOT NULL, start_time TEXT, end_time TEXT, venue TEXT, organizer TEXT, description TEXT, status TEXT NOT NULL, opponent_school TEXT, host_school TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, created_by TEXT REFERENCES users(id), updated_by TEXT REFERENCES users(id));
CREATE TABLE IF NOT EXISTS sporting_fixtures (id TEXT PRIMARY KEY, school_id TEXT NOT NULL REFERENCES schools(id), activity_id TEXT NOT NULL REFERENCES sporting_activities(id), sport_id TEXT NOT NULL REFERENCES sporting_sports(id), team_a_id TEXT REFERENCES sporting_teams(id), team_b_id TEXT REFERENCES sporting_teams(id), opponent_school TEXT, fixture_date TEXT NOT NULL, start_time TEXT, venue TEXT NOT NULL, officials TEXT, status TEXT NOT NULL, score TEXT, winner TEXT, is_draw INTEGER NOT NULL DEFAULT 0, notes TEXT, result_confirmed INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sporting_participants (id TEXT PRIMARY KEY, school_id TEXT NOT NULL REFERENCES schools(id), activity_id TEXT NOT NULL REFERENCES sporting_activities(id), student_id TEXT NOT NULL, pgsid TEXT NOT NULL, team_id TEXT REFERENCES sporting_teams(id), sport_id TEXT NOT NULL REFERENCES sporting_sports(id), event_category TEXT, participation_role TEXT, result TEXT, position INTEGER, participation_status TEXT NOT NULL, remarks TEXT, created_at TEXT NOT NULL, created_by TEXT REFERENCES users(id), UNIQUE(activity_id, student_id));
CREATE TABLE IF NOT EXISTS sporting_results (id TEXT PRIMARY KEY, school_id TEXT NOT NULL REFERENCES schools(id), activity_id TEXT NOT NULL REFERENCES sporting_activities(id), fixture_id TEXT REFERENCES sporting_fixtures(id), participant_id TEXT REFERENCES sporting_participants(id), event_name TEXT, category TEXT, team_id TEXT REFERENCES sporting_teams(id), position INTEGER, time_value TEXT, distance_value TEXT, height_value TEXT, points NUMERIC, score TEXT, winner TEXT, notes TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, created_by TEXT REFERENCES users(id));
CREATE INDEX IF NOT EXISTS idx_sporting_activity_school_date ON sporting_activities(school_id, event_date);
CREATE INDEX IF NOT EXISTS idx_sporting_fixture_school_date ON sporting_fixtures(school_id, fixture_date);
CREATE INDEX IF NOT EXISTS idx_sporting_participant_school_student ON sporting_participants(school_id, student_id);
CREATE INDEX IF NOT EXISTS idx_sporting_result_school_activity ON sporting_results(school_id, activity_id);
